-- =====================================================================
--  DADOS DE DEMONSTRAÇÃO (fictícios) — opcional
--  Preenche categorias, planos e um catálogo de exemplo para testar o app.
--  Para apagar depois: rode supabase/remover-demo.sql
--  Gerado por scripts/generate-seed.mjs — não edite à mão.
-- =====================================================================
begin;

insert into public.categories (slug, name, description, position) values
  ('bl', 'BL', 'Boys'' Love: histórias de amor entre homens.', 1),
  ('gl', 'GL', 'Girls'' Love: histórias de amor entre mulheres.', 2),
  ('romance', 'Romance', 'Para suspirar do começo ao fim.', 3),
  ('drama', 'Drama', 'Emoção, conflitos e reviravoltas.', 4),
  ('comedia', 'Comédia', 'Leves, divertidos e apaixonantes.', 5),
  ('escolar', 'Escolar', 'Amores de colégio e universidade.', 6),
  ('fantasia', 'Fantasia', 'Magia, destino e o impossível.', 7),
  ('misterio', 'Mistério', 'Segredos que prendem a atenção.', 8)
on conflict (slug) do nothing;

insert into public.plans (name, description, price_cents, type, duration_days, screens, active, highlight, position)
select v.name, v.description, v.price_cents, v.type::public.plan_type, v.duration_days, v.screens, v.active, v.highlight, v.position from (values
  ('Mensal', 'Acesso completo, renovado todo mês.', 1990, 'recorrente', 30, 1, true, false, 1),
  ('Trimestral', 'Três meses com desconto.', 4990, 'recorrente', 90, 2, true, true, 2),
  ('Anual', 'O melhor custo-benefício.', 15990, 'recorrente', 365, 3, true, false, 3),
  ('Vitalício', 'Pague uma vez, assista para sempre.', 39900, 'vitalicio', null::integer, 2, true, false, 4)
) as v(name, description, price_cents, type, duration_days, screens, active, highlight, position)
where not exists (select 1 from public.plans p where p.name = v.name);

insert into public.doramas (slug, title, original_title, tagline, synopsis, year, country, age_rating, status, visibility, is_featured, featured_position, is_new, popularity, art_seed) values
  ('amor-em-seul', 'Amor em Seul', null, 'Um contrato de seis meses. Um coração sem prazo de validade.', 'Ji-ho aceita fingir um namoro com o herdeiro de uma rede de hotéis para salvar a cafeteria da família. O que era só um acordo começa a ficar real demais — e perigoso demais para os dois.', 2026, 'Coreia do Sul', '14', 'em_exibicao', 'publicado', true, 1, true, 98, 0),
  ('ceu-de-bangkok', 'Céu de Bangkok', null, 'Dois pilotos rivais. Um único céu.', 'Na academia de aviação mais disputada da Tailândia, Phum e Win competem pela última vaga de comandante. Entre treinos noturnos e voos de teste, a rivalidade vira algo que nenhum dos dois sabe pilotar.', 2025, 'Tailândia', '14', 'completo', 'publicado', true, 2, false, 95, 4),
  ('duas-luas', 'Duas Luas', null, 'Ela escreve finais felizes. Até conhecer a sua.', 'Uma roteirista em crise criativa aluga um quarto na casa de uma fotógrafa misteriosa em Taipei. Entre noites de insônia e fotografias reveladas à mão, nasce uma história que nenhuma das duas planejou.', 2026, 'Taiwan', '12', 'em_exibicao', 'publicado', true, 3, true, 91, 3),
  ('segredo-do-campus', 'Segredo do Campus', null, 'Todo grêmio estudantil guarda um segredo.', 'Quando o presidente do grêmio descobre que o novo aluno transferido é o autor anônimo do blog que expõe a escola, os dois fazem um pacto: silêncio em troca de ajuda. Só não contavam com os sentimentos.', 2025, 'Tailândia', '12', 'completo', 'publicado', false, 0, false, 89, 5),
  ('cafe-das-7', 'Café das 7', null, 'O pedido de sempre. Um sentimento novo.', 'Todos os dias, às sete da manhã, o mesmo cliente pede o mesmo café sem dizer uma palavra. O barista decide descobrir quem ele é — e acaba descobrindo muito sobre si mesmo.', 2024, 'Japão', 'L', 'completo', 'publicado', false, 0, false, 84, 2),
  ('melodia-proibida', 'Melodia Proibida', null, 'Algumas canções não foram feitas para serem esquecidas.', 'Uma violinista prodígio e a herdeira rebelde de uma gravadora se reencontram dez anos depois de um escândalo que separou as duas. Agora, uma última apresentação pode mudar tudo.', 2025, 'Coreia do Sul', '16', 'completo', 'publicado', false, 0, false, 87, 1),
  ('luz-de-neon', 'Luz de Neon', null, 'A cidade nunca dorme. Nem os segredos dele.', 'Um detetive novato e um informante que vive nas sombras de Hong Kong precisam trabalhar juntos para resolver uma série de desaparecimentos. A verdade está mais perto do que eles imaginam.', 2026, 'China', '16', 'em_exibicao', 'publicado', false, 0, true, 82, 6),
  ('petalas-de-outono', 'Pétalas de Outono', null, 'Um amor que floresce fora de época.', 'Duas floristas de bairros rivais em Kyoto disputam o contrato do festival de outono da cidade. Arranjo após arranjo, a competição vira cumplicidade.', 2024, 'Japão', 'L', 'completo', 'publicado', false, 0, false, 76, 7),
  ('promessa-de-verao', 'Promessa de Verão', null, 'Eles prometeram voltar. Só um cumpriu.', 'Dez anos depois de um verão inesquecível numa ilha das Filipinas, Paolo volta para cumprir uma promessa de infância — e encontra Miguel prestes a se casar.', 2025, 'Filipinas', '12', 'completo', 'publicado', false, 0, false, 80, 8),
  ('jardim-de-inverno', 'Jardim de Inverno', null, 'Há flores que só nascem no frio.', 'Uma jovem herda uma estufa abandonada e descobre que ela guarda um portal para o passado — e para a mulher que a construiu cem anos atrás.', 2026, 'Coreia do Sul', '12', 'em_exibicao', 'publicado', false, 0, true, 79, 9),
  ('linhas-cruzadas', 'Linhas Cruzadas', null, 'Uma ligação errada. A pessoa certa.', 'Um atendente de call center noturno e um insone que liga todas as madrugadas criam uma amizade sem rostos. Até que um dia decidem se encontrar.', 2023, 'Taiwan', 'L', 'completo', 'publicado', false, 0, false, 72, 10),
  ('tinta-e-seda', 'Tinta e Seda', null, 'Na corte, cada pincelada é um risco.', 'Na China imperial, um pintor da corte é encarregado de retratar o príncipe exilado. Entre sessões secretas e intrigas palacianas, nasce um sentimento que pode custar a vida dos dois.', 2024, 'China', '14', 'completo', 'publicado', false, 0, false, 86, 11),
  ('entre-ondas', 'Entre Ondas', null, 'Ela queria a onda perfeita. Encontrou outra coisa.', 'Uma surfista profissional machucada volta para a vila de pescadores onde cresceu e precisa aprender a confiar de novo — no mar e na instrutora local que não sai do seu caminho.', 2025, 'Tailândia', 'L', 'completo', 'publicado', false, 0, false, 74, 12),
  ('ultimo-trem', 'Último Trem', null, 'Toda noite, o mesmo vagão. Toda noite, ele.', 'Dois desconhecidos se encontram todas as noites no último trem de Tóquio. Sem saber o nome um do outro, compartilham histórias — até que um deles para de aparecer.', 2026, 'Japão', '12', 'em_exibicao', 'publicado', false, 0, true, 88, 13)
on conflict (slug) do nothing;

